#include <stdint.h>

extern void initialise_monitor_handles(void);

int main(void) {
	initialise_monitor_handles();

	uint32_t *pClkCtrlReg = (uint32_t*) 0x40023830;

	uint32_t *pPortCModeReg = (uint32_t*) 0x40020800;
	uint32_t *pPortCOutReg = (uint32_t*) 0x40020814;

	// 1. Enable the clock for GPIOC peripheral in the AHB1ENR (SET the second bit position)
	*pClkCtrlReg |= (1 << 2);

	// 2. Configure the mode of the I/O pin as output
	// A. Clear the 26th and 27th bit positions (CLEAR)
	*pPortCModeReg &= ~(3 << 26);
	// B. Make 26th bit position as 1 (SET)
	*pPortCModeReg |= (1 << 26);

	// 3. Set 13th bit of the output data register to make I/O pin-13 as HIGH
	// NOTE: The PC13 is a active-low pin
	*pPortCOutReg |= (0 << 13);

	/* Loop forever */
	while(1);
}
